function direct_horizon_abel_numerator(s::Integer, lambda, m, nu, omega)
    s == -2 && return _h_abel_sminus2(lambda, m, nu, omega)
    s == -1 && return _h_abel_sminus1(lambda, m, nu, omega)
    s == 0 && return _h_abel_s0(lambda, m, nu, omega)
    s == 1 && return _h_abel_splus1(lambda, m, nu, omega)
    s == 2 && return _h_abel_splus2(lambda, m, nu, omega)
    throw(ArgumentError("horizon Abel coefficients support s = -2,-1,0,1,2."))
end

